# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def make_shift(worker, start, end, weekday="mon"):
    span = Span(start * 60, end * 60)
    return Shift(worker, weekday, span)


class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_one_decimal(self):
        shifts = [
            make_shift("bob", 9, 10),
            make_shift("ana", 9, 12),
            make_shift("ana", 9, 11, "tue"),
            make_shift("cyd", 9, 10, "tue"),
            make_shift("cyd", 9, 10, "wed")
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "ana: 2 shifts, 5.0 hours",
                "cyd: 2 shifts, 2.0 hours",
                "bob: 1 shifts, 1.0 hours"
            ]
        )

    def test_partial_hours_round(self):
        shifts = [Shift("ana", "mon", Span(540, 620))]
        self.assertEqual(
            timesheet_lines(shifts),
            ["ana: 1 shifts, 1.3 hours"]
        )

    def test_empty_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for blank in ("", "   "):
            with self.assertRaises(ProjectError):
                timesheet_lines([make_shift(blank, 9, 10)])


if __name__ == "__main__":
    unittest.main()
